#### Phase 2: Implementation (Week 3-6)

**Step 1: Create BFF/Composer Service**

```csharp
// MemberBFF/Controllers/MemberDashboardController.cs
using Microsoft.AspNetCore.Mvc;
using System.Threading.Tasks;
using System.Collections.Generic;

[ApiController]
[Route("api/members")]
public class MemberDashboardController : ControllerBase
{
    private readonly IMemberDashboardComposer _composer;
    private readonly IDistributedCache _cache;
    private readonly ILogger<MemberDashboardController> _logger;

    public MemberDashboardController(
        IMemberDashboardComposer composer,
        IDistributedCache cache,
        ILogger<MemberDashboardController> logger)
    {
        _composer = composer;
        _cache = cache;
        _logger = logger;
    }

    [HttpGet("{memberId}/dashboard")]
    [ProducesResponseType(typeof(MemberDashboardResponse), StatusCodes.Status200OK)]
    [ProducesResponseType(typeof(PartialMemberDashboardResponse), StatusCodes.Status206PartialContent)]
    public async Task<IActionResult> GetMemberDashboard(
        string memberId,
        [FromQuery] bool includeRecentClaims = true,
        [FromQuery] int claimsLimit = 5)
    {
        var cacheKey = $"dashboard:{memberId}:{includeRecentClaims}:{claimsLimit}";

        // Check cache
        var cachedResponse = await _cache.GetStringAsync(cacheKey);
        if (cachedResponse != null)
        {
            _logger.LogInformation("Cache hit for member dashboard: {MemberId}", memberId);
            return Ok(JsonSerializer.Deserialize<MemberDashboardResponse>(cachedResponse));
        }

        // Compose response from multiple services
        var compositionResult = await _composer.ComposeMemberDashboard(
            memberId,
            includeRecentClaims,
            claimsLimit);

        // Handle partial failures
        if (compositionResult.HasErrors)
        {
            _logger.LogWarning(
                "Partial dashboard composition for member {MemberId}. Errors: {ErrorCount}",
                memberId,
                compositionResult.Errors.Count);
            return StatusCode(206, compositionResult); // 206 Partial Content
        }

        // Cache successful response (5 minute TTL)
        await _cache.SetStringAsync(
            cacheKey,
            JsonSerializer.Serialize(compositionResult),
            new DistributedCacheEntryOptions
            {
                AbsoluteExpirationRelativeToNow = TimeSpan.FromMinutes(5)
            });

        return Ok(compositionResult);
    }
}
```

**Step 2: Implement Composer with Parallel Execution**

```csharp
// MemberBFF/Services/MemberDashboardComposer.cs
using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;
using Polly;
using Polly.CircuitBreaker;

public class MemberDashboardComposer : IMemberDashboardComposer
{
    private readonly IHttpClientFactory _httpClientFactory;
    private readonly ILogger<MemberDashboardComposer> _logger;
    private readonly IAsyncPolicy<HttpResponseMessage> _resiliencePolicy;

    public MemberDashboardComposer(
        IHttpClientFactory httpClientFactory,
        ILogger<MemberDashboardComposer> logger)
    {
        _httpClientFactory = httpClientFactory;
        _logger = logger;

        // Configure resilience policy with circuit breaker and retry
        _resiliencePolicy = Policy
            .Handle<HttpRequestException>()
            .OrResult<HttpResponseMessage>(r => !r.IsSuccessStatusCode)
            .WaitAndRetryAsync(
                retryCount: 3,
                sleepDurationProvider: retryAttempt =>
                    TimeSpan.FromMilliseconds(100 * Math.Pow(2, retryAttempt)),
                onRetry: (outcome, timespan, retryCount, context) =>
                {
                    _logger.LogWarning(
                        "Retry {RetryCount} after {Delay}ms for {Service}",
                        retryCount, timespan.TotalMilliseconds, context["service"]);
                })
            .WrapAsync(Policy
                .Handle<HttpRequestException>()
                .OrResult<HttpResponseMessage>(r => !r.IsSuccessStatusCode)
                .CircuitBreakerAsync(
                    handledEventsAllowedBeforeBreaking: 5,
                    durationOfBreak: TimeSpan.FromSeconds(30),
                    onBreak: (outcome, duration) =>
                    {
                        _logger.LogError(
                            "Circuit breaker opened for {Duration}s",
                            duration.TotalSeconds);
                    },
                    onReset: () =>
                    {
                        _logger.LogInformation("Circuit breaker reset");
                    }));
    }

    public async Task<MemberDashboardResponse> ComposeMemberDashboard(
        string memberId,
        bool includeRecentClaims,
        int claimsLimit)
    {
        using var activity = Activity.Current?.Source.StartActivity("ComposeMemberDashboard");
        activity?.SetTag("memberId", memberId);

        var response = new MemberDashboardResponse
        {
            Metadata = new ResponseMetadata
            {
                GeneratedAt = DateTime.UtcNow,
                RequestId = Activity.Current?.Id ?? Guid.NewGuid().ToString()
            }
        };

        // Phase 1: Parallel calls for independent services
        var phase1Tasks = new List<Task>
        {
            FetchMemberData(memberId, response),
            FetchEligibilityData(memberId, response),
            FetchAssignedProviders(memberId, response)
        };

        await Task.WhenAll(phase1Tasks);

        // Phase 2: Dependent calls (only if we have member data)
        if (response.Member != null && includeRecentClaims)
        {
            var phase2Tasks = new List<Task>
            {
                FetchRecentClaims(memberId, claimsLimit, response),
                FetchCarePlans(memberId, response)
            };

            await Task.WhenAll(phase2Tasks);
        }

        // Calculate completeness
        var totalFields = 5;
        var populatedFields = new[]
        {
            response.Member,
            response.Eligibility,
            response.AssignedProviders,
            response.RecentClaims,
            response.CarePlans
        }.Count(f => f != null);

        response.Metadata.Completeness = $"{(populatedFields * 100 / totalFields)}%";
        response.HasErrors = response.Errors.Any();

        return response;
    }

    private async Task FetchMemberData(string memberId, MemberDashboardResponse response)
    {
        try
        {
            using var activity = Activity.Current?.Source.StartActivity("FetchMemberData");
            var client = _httpClientFactory.CreateClient("MemberService");

            var context = new Context { ["service"] = "MemberService" };
            var httpResponse = await _resiliencePolicy.ExecuteAsync(
                ctx => client.GetAsync($"/api/members/{memberId}"),
                context);

            if (httpResponse.IsSuccessStatusCode)
            {
                var content = await httpResponse.Content.ReadAsStringAsync();
                response.Member = JsonSerializer.Deserialize<MemberSummary>(content);
                _logger.LogInformation("Successfully fetched member data for {MemberId}", memberId);
            }
            else
            {
                throw new HttpRequestException($"Member service returned {httpResponse.StatusCode}");
            }
        }
        catch (BrokenCircuitException ex)
        {
            _logger.LogError(ex, "Circuit breaker open for Member Service");
            response.Errors.Add(new ServiceError
            {
                Service = "MemberService",
                Code = "CIRCUIT_BREAKER_OPEN",
                Message = "Member service temporarily unavailable"
            });
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error fetching member data for {MemberId}", memberId);
            response.Errors.Add(new ServiceError
            {
                Service = "MemberService",
                Code = "SERVICE_ERROR",
                Message = "Unable to fetch member data"
            });
        }
    }

    private async Task FetchEligibilityData(string memberId, MemberDashboardResponse response)
    {
        try
        {
            using var activity = Activity.Current?.Source.StartActivity("FetchEligibilityData");
            var client = _httpClientFactory.CreateClient("EligibilityService");

            var context = new Context { ["service"] = "EligibilityService" };
            var httpResponse = await _resiliencePolicy.ExecuteAsync(
                ctx => client.GetAsync($"/api/eligibility/{memberId}/current"),
                context);

            if (httpResponse.IsSuccessStatusCode)
            {
                var content = await httpResponse.Content.ReadAsStringAsync();
                response.Eligibility = JsonSerializer.Deserialize<EligibilitySummary>(content);
            }
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error fetching eligibility for {MemberId}", memberId);
            response.Errors.Add(new ServiceError
            {
                Service = "EligibilityService",
                Code = "SERVICE_ERROR",
                Message = "Unable to fetch eligibility data"
            });
        }
    }

    private async Task FetchRecentClaims(string memberId, int limit, MemberDashboardResponse response)
    {
        try
        {
            using var activity = Activity.Current?.Source.StartActivity("FetchRecentClaims");
            var client = _httpClientFactory.CreateClient("ClaimsService");

            var context = new Context { ["service"] = "ClaimsService" };
            var httpResponse = await _resiliencePolicy.ExecuteAsync(
                ctx => client.GetAsync($"/api/claims?memberId={memberId}&limit={limit}"),
                context);

            if (httpResponse.IsSuccessStatusCode)
            {
                var content = await httpResponse.Content.ReadAsStringAsync();
                response.RecentClaims = JsonSerializer.Deserialize<List<ClaimSummary>>(content);
            }
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error fetching claims for {MemberId}", memberId);
            response.Errors.Add(new ServiceError
            {
                Service = "ClaimsService",
                Code = "SERVICE_ERROR",
                Message = "Unable to fetch recent claims"
            });
        }
    }

    private async Task FetchAssignedProviders(string memberId, MemberDashboardResponse response)
    {
        // Similar implementation to above methods
    }

    private async Task FetchCarePlans(string memberId, MemberDashboardResponse response)
    {
        // Similar implementation to above methods
    }
}
```

**Step 3: Configure HTTP Clients with Service Discovery**

```csharp
// Program.cs or Startup.cs
services.AddHttpClient("MemberService", client =>
{
    client.BaseAddress = new Uri("http://member-service:8080");
    client.DefaultRequestHeaders.Add("Accept", "application/json");
    client.Timeout = TimeSpan.FromSeconds(10);
})
.AddPolicyHandler(GetRetryPolicy())
.AddPolicyHandler(GetCircuitBreakerPolicy());

services.AddHttpClient("EligibilityService", client =>
{
    client.BaseAddress = new Uri("http://eligibility-service:8080");
    client.DefaultRequestHeaders.Add("Accept", "application/json");
    client.Timeout = TimeSpan.FromSeconds(10);
})
.AddPolicyHandler(GetRetryPolicy())
.AddPolicyHandler(GetCircuitBreakerPolicy());

services.AddHttpClient("ClaimsService", client =>
{
    client.BaseAddress = new Uri("http://claims-service:8080");
    client.DefaultRequestHeaders.Add("Accept", "application/json");
    client.Timeout = TimeSpan.FromSeconds(15); // Claims queries may be slower
})
.AddPolicyHandler(GetRetryPolicy())
.AddPolicyHandler(GetCircuitBreakerPolicy());

// Configure distributed cache
services.AddStackExchangeRedisCache(options =>
{
    options.Configuration = configuration["Redis:ConnectionString"];
    options.InstanceName = "MemberBFF:";
});

static IAsyncPolicy<HttpResponseMessage> GetRetryPolicy()
{
    return HttpPolicyExtensions
        .HandleTransientHttpError()
        .WaitAndRetryAsync(3, retryAttempt =>
            TimeSpan.FromMilliseconds(100 * Math.Pow(2, retryAttempt)));
}

static IAsyncPolicy<HttpResponseMessage> GetCircuitBreakerPolicy()
{
    return HttpPolicyExtensions
        .HandleTransientHttpError()
        .CircuitBreakerAsync(5, TimeSpan.FromSeconds(30));
}
```

